//! Entry point: triangulate a gear-shaped polygon and print the triangle
//! indices.
//!
//! Usage: `test11 [n]` — `n` is the number of gear teeth (default 11), parsed
//! with C `atoi` semantics.

mod cli;
mod earcut;
mod gear;

use std::io::{self, BufWriter, Write};

fn main() {
    let n = cli::parse_n(std::env::args());

    let polygon = gear::gear_polygon(n);

    let indices = earcut::earcut(&polygon);

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    for idx in &indices {
        let _ = write!(out, "{} ", idx);
    }
    let _ = out.flush();
}
